module protocol::asset_admin;

use std::type_name::TypeName;
use sui::clock::Clock;
use sui::event::emit;

use protocol::error;
use protocol::app::{AdminCap, ProtocolApp};
use protocol::market::Market;
use protocol::interest::InterestModel;
use protocol::asset::AssetConfig;

const ASSET_MARKET_CONFIG: u8 = 0;
const ASSET_INTEREST_MODEL: u8 = 1;
const ASSET_BORROW_PAUSE_STATE: u8 = 2;
// fource more fields reserved, 3 - 6

const DECIMAL_DENOMINATOR: u64 = 10000;
const PRICISE_DECIMAL_DENOMINATOR: u64 = 1000000000000000000;

public struct AssetOnboardedEvent has copy, drop {
    market: TypeName,
    interest_model: InterestModel,
    asset_config: AssetConfig,
    time: u64,
    operator: address,
}

public struct AssetUpdated<T> has copy, drop {
    what: u8,
    market: TypeName,
    asset: TypeName,
    new: T
}

public fun onboard_new_asset<MarketType, CoinType>(
    _: &AdminCap,
    self: &ProtocolApp,
    market: &mut Market<MarketType>,
    interest_model: InterestModel,
    asset_config: AssetConfig,
    clock: &Clock,
    ctx: &mut TxContext,
) {
    assert!(!market.has_circuit_break_triggered(), error::market_under_circuit_break());

    self.validate_market<MarketType>(market);
    self.ensure_version_matches();

    let now = clock.timestamp_ms() / 1000;
    market.onboard_new_asset<MarketType, CoinType>(
        interest_model,
        asset_config,
        now,
        ctx,
    );


    emit(AssetOnboardedEvent {
        market: std::type_name::with_defining_ids<MarketType>(),
        interest_model,
        asset_config,
        time: now,
        operator: ctx.sender(),
    });
}

/// Create a asset configuration
public fun create_market_asset_config(
    _: &AdminCap,
    self: &ProtocolApp,
    min_borrow_amount: u64,
    max_borrow_amount: u64,
    max_deposit_amount: u64,
    repay_fee_rate: u64, // basis points
    liquidation_fee_rate: u64, // basis points
): AssetConfig {
    // Validate parameters
    assert!(min_borrow_amount > 0, error::invalid_params_error());
    assert!(liquidation_fee_rate <= DECIMAL_DENOMINATOR, error::invalid_params_error());
    assert!(repay_fee_rate <= DECIMAL_DENOMINATOR, error::invalid_params_error());

    self.ensure_version_matches();

    let liquidation_fee = math::float::from_quotient(liquidation_fee_rate, DECIMAL_DENOMINATOR);
    let repay_fee = math::float::from_quotient(repay_fee_rate, DECIMAL_DENOMINATOR);

    protocol::asset::new_asset_config(
        min_borrow_amount,
        max_borrow_amount,
        repay_fee,
        max_deposit_amount,
        liquidation_fee
    )
}

/// Update borrow configuration for an asset
public fun update_market_asset_config<MarketType, CoinType>(
    _: &AdminCap,
    self: &ProtocolApp,
    market: &mut Market<MarketType>,
    asset_config: AssetConfig,
) {
    self.validate_market<MarketType>(market);
    self.ensure_version_matches();

    assert!(!market.has_circuit_break_triggered(), error::market_under_circuit_break());

    let asset = market.market_asset_borrow_mut<MarketType, CoinType>();
    asset.update_asset_config<MarketType>(asset_config);

    emit(AssetUpdated<AssetConfig>{
        what: ASSET_MARKET_CONFIG,
        market: std::type_name::with_defining_ids<MarketType>(),
        asset: std::type_name::with_defining_ids<CoinType>(),
        new: asset_config
    });
}

public fun update_market_asset_interest_model<MarketType, CoinType>(
    _: &AdminCap,
    self: &ProtocolApp,
    market: &mut Market<MarketType>,
    interest_model: InterestModel,
) {
    self.validate_market<MarketType>(market);
    self.ensure_version_matches();

    assert!(!market.has_circuit_break_triggered(), error::market_under_circuit_break());

    let asset = market.market_asset_borrow_mut<MarketType, CoinType>();
    asset.update_interest_model<MarketType>(interest_model);

    emit(AssetUpdated<InterestModel>{
        what: ASSET_INTEREST_MODEL,
        market: std::type_name::with_defining_ids<MarketType>(),
        asset: std::type_name::with_defining_ids<CoinType>(),
        new: interest_model
    });
}

public fun update_asset_paused_state<MarketType, CoinType>(
    _: &AdminCap,
    self: &ProtocolApp,
    market: &mut Market<MarketType>,
    what: u8,
    is_paused: bool
) {
    self.validate_market<MarketType>(market);
    self.ensure_version_matches();

    assert!(!market.has_circuit_break_triggered(), error::market_under_circuit_break());

    let asset = market.market_asset_borrow_mut<MarketType, CoinType>();
    asset.change_operation_status<MarketType>(what, is_paused);

    emit(AssetUpdated<bool>{
        what: ASSET_BORROW_PAUSE_STATE + what,
        market: std::type_name::with_defining_ids<MarketType>(),
        asset: std::type_name::with_defining_ids<CoinType>(),
        new: is_paused,
    });
}

/// Create an interest model
public fun create_interest_model(
    admin_cap: &AdminCap,
    self: &ProtocolApp,
    base_rate_per_sec: u64,
    borrow_rate_on_mid_kink: u64,
    mid_kink: u64,
    borrow_rate_on_high_kink: u64,
    high_kink: u64,
    max_borrow_rate: u64,
): InterestModel {
    assert!(mid_kink > 0, error::invalid_params_error());
    assert!(mid_kink < high_kink && high_kink < DECIMAL_DENOMINATOR, error::invalid_params_error());
    assert!(base_rate_per_sec <= borrow_rate_on_mid_kink, error::invalid_params_error());
    assert!(borrow_rate_on_mid_kink <= borrow_rate_on_high_kink && borrow_rate_on_high_kink <= max_borrow_rate, error::invalid_params_error());

    self.ensure_version_matches();

    create_interest_model_inner(admin_cap, base_rate_per_sec, borrow_rate_on_mid_kink, mid_kink, borrow_rate_on_high_kink, high_kink, max_borrow_rate)
}

fun create_interest_model_inner(
    _: &AdminCap,
    base_rate_per_sec: u64,
    borrow_rate_on_mid_kink: u64,
    mid_kink: u64,
    borrow_rate_on_high_kink: u64,
    high_kink: u64,
    max_borrow_rate: u64,
): InterestModel {
    // Convert u64 values to UQ64_64 for the interest model
    let base_rate = math::float::from_quotient(base_rate_per_sec, PRICISE_DECIMAL_DENOMINATOR);
    let mid_kink_rate = math::float::from_quotient(
        borrow_rate_on_mid_kink,
        PRICISE_DECIMAL_DENOMINATOR,
    );
    let mid_kink_util = math::float::from_quotient(mid_kink, DECIMAL_DENOMINATOR);
    let high_kink_rate = math::float::from_quotient(
        borrow_rate_on_high_kink,
        PRICISE_DECIMAL_DENOMINATOR,
    );
    let high_kink_util = math::float::from_quotient(high_kink, DECIMAL_DENOMINATOR);
    let max_rate = math::float::from_quotient(max_borrow_rate, PRICISE_DECIMAL_DENOMINATOR);

    protocol::interest::new(
        base_rate,
        mid_kink_rate,
        mid_kink_util,
        high_kink_rate,
        high_kink_util,
        max_rate,
    )
}

// allow testing interest rate much larger than production allowed 
#[test_only]
public fun create_interest_model_test(
    admin_cap: &AdminCap,
    base_rate_per_sec: u64,
    borrow_rate_on_mid_kink: u64,
    mid_kink: u64,
    borrow_rate_on_high_kink: u64,
    high_kink: u64,
    max_borrow_rate: u64,
): InterestModel {
    create_interest_model_inner(admin_cap, base_rate_per_sec, borrow_rate_on_mid_kink, mid_kink, borrow_rate_on_high_kink, high_kink, max_borrow_rate)
}

